import * as styles from "./grid.module.css";
import GridCell from "./grid-cell";
import GridRow from "./grid-row";
import {useEffect, useState} from "react";
import {GUESSES_ALLOWED} from "../../constants";
import {ALLOWED_WORDS} from "../../word-list";
import Keyboard from "../keyboard/keyboard";

const target = 'HELLO';
//const target = ALLOWED_WORDS[Math.floor(Math.random() * ALLOWED_WORDS.length)];;

function Grid({modalActive}) {
    const [gameEnded, setGameEnded] = useState(null);
    const [pendingGuess, setPendingGuess] = useState('');
    const [pendingError, setPendingError] = useState(null);
    const [guesses, setGuesses] = useState([]);

    const showError = (message) => {
        setPendingError(message);
        setTimeout(() => {
            setPendingError(null)
        }, 2000);
    }

    const endGame = (success) => {
        setGameEnded(success);
    }

    const addGuess = () => {
        if(pendingGuess === target) {
            endGame(true);
        } else if(!ALLOWED_WORDS.includes(pendingGuess.toLowerCase())){
            showError('Guess is not in the list of allowed words');
        } else if(guesses.includes(pendingGuess)){
            showError('This word has already been guessed');
        } else {
            setGuesses(prev => [...prev, pendingGuess]);
            setPendingGuess('');

            if(guesses.length === GUESSES_ALLOWED - 1){
                endGame(false);
            }
        }
    };

    const getGuessForRow = (row) => {
        if(row < guesses.length){
            return guesses[row];
        } else if(row === guesses.length){
            return pendingGuess.padEnd(5, ' ');
        }
        return '     ';
    };

    const onKeyPress = (key) => {
        if(modalActive) return;

        if(key === 'ENTER' || key === '⏎'){
            addGuess();
        } else if(key === 'DELETE' || key === 'BACKSPACE' || key === '⌫') {
            setPendingGuess(prev => prev.substring(0, prev.length - 1));
        } else if(pendingGuess.length < 5) {
            setPendingGuess(prev => prev.concat(key));
        }
    };

    return (
        <div className={styles.wrapper}>
            {[...Array(GUESSES_ALLOWED).keys()].map((_, i) => {
                const isActive = gameEnded === null && i === guesses.length;
                const isError = isActive && pendingError != null;

                return (
                    <GridRow
                        key={`grid-row-${i}`}
                        active={isActive}
                        guess={getGuessForRow(i)}
                        target={target}
                        error={isError}/>
                    );
            })}

            <span className={styles.error}>{pendingError}</span>
            {gameEnded && (
                <span className={styles.success}>
                    You've completed this edition of <span style={{fontFamily: '"Bokor", system-ui'}}>Legally Distinct Word</span> game, congratulations!
                </span>
            )}

            <div className={styles.guesser}>
                <Keyboard onPress={modalActive ? null : onKeyPress}/>
            </div>
        </div>
    );
}
export default Grid;